package com.viswa2k.smsforwarder.data.repo

import android.content.Context
import com.viswa2k.smsforwarder.classify.KeywordSource

/** Reads the bundled `assets/keywords.json` (spec 05a lists, generated by `tools/extract_keywords.py`). */
class AssetKeywordSource(private val context: Context) : KeywordSource {
    override fun readText(): String =
        context.assets.open(KeywordSource.ASSET_NAME).bufferedReader(Charsets.UTF_8).use { it.readText() }
}
